// ===== Aiuti comuni del workflow 06 =====
// (Questo blocco è uguale in più nodi Code: si modifica nel generatore, non a mano nel workflow.)
const STATI_COPERTI = ['da_approvare', 'approvato', 'in_pubblicazione', 'pubblicato', 'errore'];
const STATI_PIANIFICATI = ['', 'idea', 'bozza', 'da_scrivere', 'in_scrittura'];
const STATI_DA_RIFARE = ['', 'idea', 'bozza', 'da_scrivere'];
const CARTELLA_MIME = 'application/vnd.google-apps.folder';
const GIORNI_SETTIMANA = ['domenica', 'lunedì', 'martedì', 'mercoledì', 'giovedì', 'venerdì', 'sabato'];
const MESI = ['gennaio', 'febbraio', 'marzo', 'aprile', 'maggio', 'giugno', 'luglio', 'agosto', 'settembre', 'ottobre', 'novembre', 'dicembre'];
const MARCHIO_NEUTRO = { colori: { primario: '#222222', secondario: '#F5F5F5', testo: '#FFFFFF' }, font: 'Roboto', logo: '', accento: '' };

function testo(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function norm(v) { return testo(v).toLowerCase(); }
function senzaAccenti(s) { return String(s).normalize('NFD').replace(/[̀-ͯ]/g, ''); }
function siNo(v) { return ['si', 'sì', 'yes', 'true', '1', 'x', 'vero', 'attivo', 'ok'].includes(norm(v)); }
// Peso del titolo per l'officina: 100, 200 … 900; 0 se manca o non è valido.
function pesoTitolo(v) { const n = Number(testo(v)); return testo(v) && Number.isInteger(n) && n >= 100 && n <= 900 && n % 100 === 0 ? n : 0; }
function intero(v, predefinito) { const n = parseInt(v, 10); return Number.isFinite(n) ? n : predefinito; }
function numero(v, predefinito) {
  if (v === null || v === undefined || v === '') return predefinito;
  const n = Number(String(v).replace(',', '.'));
  return Number.isFinite(n) ? n : predefinito;
}
function slug(v) {
  const s = senzaAccenti(norm(v)).replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 24);
  return s || 'cliente';
}
function oraValida(v) {
  const m = testo(v).match(/^(\d{1,2})[:.](\d{2})$/);
  if (!m) return '';
  const h = Number(m[1]);
  const mi = Number(m[2]);
  if (h > 23 || mi > 59) return '';
  return String(h).padStart(2, '0') + ':' + m[2];
}
function partiRoma(d) {
  const f = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const p = {};
  for (const x of f.formatToParts(d)) p[x.type] = x.value;
  return { data: p.year + '-' + p.month + '-' + p.day, ora: p.hour + ':' + p.minute };
}
function adesso() { return new Date(); }
function timbro() { const p = partiRoma(adesso()); return p.data.split('-').reverse().join('/') + ' ' + p.ora; }
function aggiungiGiorni(dataIso, n) {
  const [y, m, g] = dataIso.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, g + n)).toISOString().slice(0, 10);
}
function minutiDi(dataIso, ora) {
  const [y, m, g] = dataIso.split('-').map(Number);
  const [h, mi] = (ora || '00:00').split(':').map(Number);
  return Date.UTC(y, m - 1, g, h, mi) / 60000;
}
function giornoUmano(dataIso) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(testo(dataIso))) return testo(dataIso);
  const [y, m, g] = dataIso.split('-').map(Number);
  const d = new Date(Date.UTC(y, m - 1, g));
  return GIORNI_SETTIMANA[d.getUTCDay()] + ' ' + g + ' ' + MESI[m - 1];
}
// Legge "2026-12-01 11:30", "01/12/2026 11:30:00" o il numero di serie di Google Sheets.
function leggiDataOra(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number' && Number.isFinite(v)) {
    const d = new Date(Math.round((v - 25569) * 86400000));
    return { data: d.toISOString().slice(0, 10), ora: d.toISOString().slice(11, 16) };
  }
  const s = testo(v);
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[ T](\d{1,2})[:.](\d{2}))?/);
  if (m) return { data: m[1] + '-' + m[2].padStart(2, '0') + '-' + m[3].padStart(2, '0'), ora: m[4] ? m[4].padStart(2, '0') + ':' + m[5] : '' };
  m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})(?:[ ,T]+(\d{1,2})[:.](\d{2}))?/);
  if (m) return { data: m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0'), ora: m[4] ? m[4].padStart(2, '0') + ':' + m[5] : '' };
  return null;
}
function lista(v) { return testo(v).split('|').map((x) => x.trim()).filter(Boolean); }
function idDrive(v) {
  const s = testo(v);
  const m = s.match(/\/d\/([A-Za-z0-9_-]{10,})/) || s.match(/[?&]id=([A-Za-z0-9_-]{10,})/) || s.match(/\/folders\/([A-Za-z0-9_-]{10,})/);
  if (m) return m[1];
  if (/^[A-Za-z0-9_-]{10,}$/.test(s)) return s;
  return '';
}
function linkDrive(id) { return 'https://drive.google.com/file/d/' + id + '/view'; }
function piattaformeDi(c) {
  const ig = testo(c.ig_user_id);
  const fb = testo(c.fb_page_id);
  return ig && fb ? 'ig+fb' : ig ? 'ig' : fb ? 'fb' : '';
}
function unisciNota(prima, nuova) {
  const p = testo(prima);
  const n = testo(nuova);
  const tutto = p ? p + ' · ' + n : n;
  return tutto.length > 480 ? '…' + tutto.slice(-479) : tutto;
}
function coloreValido(c) { return /^#[0-9a-fA-F]{6}$/.test(testo(c)); }
function urlPubblico(v) { return /^https:\/\/[^\s\/]+\.[^\s]+$/i.test(testo(v)) ? testo(v) : ''; }
// Il logo può essere un link Drive (https://drive.google.com/file/d/<ID>/view, o l'ID) oppure un URL pubblico https qualsiasi.
function leggiLogo(v) {
  const s = testo(v);
  if (!s) return { logo_drive_id: '', logo_url: '', valido: true };
  const daDrive = /drive\.google\.com|docs\.google\.com/i.test(s) || !/^https?:/i.test(s);
  if (daDrive) { const id = idDrive(s); return { logo_drive_id: id, logo_url: '', valido: !!id }; }
  const u = urlPubblico(s);
  return { logo_drive_id: '', logo_url: u, valido: !!u };
}
function leggiMarchio(v) {
  const neutro = JSON.parse(JSON.stringify(MARCHIO_NEUTRO));
  const s = testo(v);
  const vuoto = Object.assign(neutro, { logo_drive_id: '', logo_url: '', font_testo: '', peso_titolo: 0, stile_foto: null, placid: { storia: '', post: '' } });
  if (!s) return { marchio: vuoto, valido: false, motivo: 'vuoto' };
  let m;
  try { m = JSON.parse(s); } catch (e) { return { marchio: vuoto, valido: false, motivo: 'non valido (non è un JSON scritto bene)' }; }
  if (!m || typeof m !== 'object' || Array.isArray(m)) return { marchio: vuoto, valido: false, motivo: 'non valido' };
  const col = m.colori && typeof m.colori === 'object' ? m.colori : {};
  const problemi = [];
  const colori = {};
  for (const k of ['primario', 'secondario', 'testo']) {
    if (coloreValido(col[k])) colori[k] = testo(col[k]);
    else { colori[k] = MARCHIO_NEUTRO.colori[k]; problemi.push('colore ' + k); }
  }
  const font = testo(m.font);
  if (!font) problemi.push('font');
  const logo = leggiLogo(m.logo);
  if (!logo.valido) problemi.push('link del logo (serve un link Drive o un indirizzo https)');
  const pl = m.placid && typeof m.placid === 'object' ? m.placid : {};
  return {
    marchio: {
      colori, accento: coloreValido(col.accento) ? testo(col.accento) : '', font: font || MARCHIO_NEUTRO.font, font_testo: testo(m.font_testo),
      peso_titolo: pesoTitolo(m.peso_titolo),
      logo: testo(m.logo), logo_drive_id: logo.logo_drive_id, logo_url: logo.logo_url,
      stile_foto: m.stile_foto && typeof m.stile_foto === 'object' ? m.stile_foto : null,
      placid: { storia: testo(pl.storia), post: testo(pl.post) },
    },
    valido: problemi.length === 0,
    motivo: problemi.length ? 'incompleto (' + problemi.join(', ') + ')' : '',
  };
}
// ----- Testi per Telegram -----
// Messaggi normali: parse_mode HTML, quindi & < > vanno protetti. Domanda Approva/Rifiuta: Markdown (fisso in n8n), si proteggono _ * ` [.
function escHtml(v) { return String(v === null || v === undefined ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function escMd(v) { return String(v === null || v === undefined ? '' : v).replace(/([_*`\[])/g, '\\$1'); }
