function righeStorie(cal, cliente, data) {
  return cal.filter((r) => norm(r.tipo) === 'storia' && testo(r.cliente) === cliente && (leggiDataOra(r.data_ora) || {}).data === data);
}
function perRiga(a, b) { return (Number(a.row_number) || 0) - (Number(b.row_number) || 0); }
function eTentativoNostro(r) { return testo(r.media) !== '' && STATI_DA_RIFARE.includes(norm(r.stato)) && testo(r.note).includes('[06]'); }
function copreIlGiorno(r) { return testo(r.media) !== '' && !eTentativoNostro(r); }
// Il giorno è scoperto se non c'è nessuna storia con media (tranne le nostre rifiutate o scadute)
// e nessuno la sta preparando adesso.
function statoGiorno(cal, cliente, data, cfg) {
  const righe = righeStorie(cal, cliente, data).sort(perRiga);
  const coperta = righe.find(copreIlGiorno);
  if (coperta) return { scoperto: false, motivo: 'coperto', riga: coperta };
  const inCorso = righe.find((r) => !testo(r.media) && norm(r.stato) === 'in_scrittura' && testo(r.esecuzione));
  if (inCorso) return { scoperto: false, motivo: 'in_lavorazione', riga: inCorso };
  const tentativi = righe.filter(eTentativoNostro).length;
  if (tentativi >= Math.max(intero(cfg.MAX_TENTATIVI_GIORNO, 2), 1)) return { scoperto: false, motivo: 'troppi_tentativi', tentativi };
  const pianificata = righe.find((r) => !testo(r.media) && STATI_PIANIFICATI.includes(norm(r.stato)) && !testo(r.esecuzione)) || null;
  return { scoperto: true, pianificata, tentativi };
