// ----- Foglio Google letto con l'API Sheets (nodo HTTP Request): { range, values: [[intestazione], [riga], ...] } -----
const COLONNE_CALENDARIO = ['id', 'cliente', 'tipo', 'piattaforme', 'data_ora', 'didascalia', 'primo_commento', 'media', 'copertina', 'stato',
  'esecuzione', 'link_ig', 'link_fb', 'pubblicato_il', 'errore', 'note', 'brief', 'tag_persone', 'collaboratori', 'luogo'];
function tabellaDa(json) {
  const j = json || {};
  const v = Array.isArray(j.values) ? j.values : [];
  const m = testo(j.range).match(/![A-Z]+(\d+)/);
  const inizio = m ? Number(m[1]) : 1;
  const intestazione = (v[0] || []).map((h) => testo(h));
  const righe = [];
  for (let i = 1; i < v.length; i++) {
    const r = Array.isArray(v[i]) ? v[i] : [];
    if (!r.some((c) => testo(c) !== '')) continue;
    const o = { row_number: inizio + i };
    intestazione.forEach((h, k) => { if (h) o[h] = r[k] === undefined || r[k] === null ? '' : r[k]; });
    righe.push(o);
  }
  return { intestazione, righe, errore: j.error ? testo(typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error))).slice(0, 200) : '' };
}
function tabella(nomeNodo) { const it = $(nomeNodo).first(); return tabellaDa(it ? it.json : {}); }
function colonna(k) { let s = ''; let n = k + 1; while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; }
// Scrittura per id: la riga è quella appena riletta (row_number); si scrivono solo le colonne indicate, trovate per nome, in RAW.
function corpoAggiorna(tab, foglio, rowNumber, valori) {
  if (!(Number(rowNumber) >= 2)) throw new Error('Riga del foglio ' + foglio + ' non valida: ' + rowNumber);
  const data = [];
  for (const [k, v] of Object.entries(valori)) {
    const i = tab.intestazione.indexOf(k);
    if (i < 0) throw new Error('Nel foglio ' + foglio + ' manca la colonna «' + k + '» nella prima riga');
    data.push({ range: foglio + '!' + colonna(i) + rowNumber, values: [[v === null || v === undefined ? '' : String(v)]] });
  }
  return { valueInputOption: 'RAW', data };
}
function corpoAggiungi(tab, valori) {
  const intest = tab.intestazione.filter(Boolean).length ? tab.intestazione : COLONNE_CALENDARIO;
  for (const k of Object.keys(valori)) if (!intest.includes(k)) throw new Error('Nel Calendario manca la colonna «' + k + '» nella prima riga');
  return { values: [intest.map((h) => (h && h in valori ? String(valori[h] === null || valori[h] === undefined ? '' : valori[h]) : ''))] };
}
// ----- Cloudflare R2 (pacchetto PRO): indirizzi pubblici dei file caricati -----
function r2Pronto(cfg) { return !!testo(cfg.R2_BUCKET) && !/^INSERISCI/i.test(testo(cfg.R2_BUCKET)) && !!urlPubblico(cfg.R2_PUBLIC_BASE_URL); }
function chiaveR2(prefisso, cliente, nome) { return prefisso + '/' + slug(cliente) + '/' + String(nome).replace(/[^A-Za-z0-9._-]+/g, '-').slice(0, 120); }
function urlR2(cfg, chiave) { return testo(cfg.R2_PUBLIC_BASE_URL).replace(/\/+$/, '') + '/' + chiave; }
function righeStorie(cal, cliente, data) {
  return cal.filter((r) => norm(r.tipo) === 'storia' && testo(r.cliente) === cliente && (leggiDataOra(r.data_ora) || {}).data === data);
}
function perRiga(a, b) { return (Number(a.row_number) || 0) - (Number(b.row_number) || 0); }
function eTentativoNostro(r) { return testo(r.media) !== '' && STATI_DA_RIFARE.includes(norm(r.stato)) && testo(r.note).includes('[06]'); }
function copreIlGiorno(r) { return testo(r.media) !== '' && !eTentativoNostro(r); }
// Il giorno è scoperto se non c'è nessuna storia con media (tranne le nostre rifiutate o scadute)
// e nessuno la sta preparando adesso.
function statoGiorno(cal, cliente, data, cfg) {
  const righe = righeStorie(cal, cliente, data).sort(perRiga);
  const coperta = righe.find(copreIlGiorno);
  if (coperta) return { scoperto: false, motivo: 'coperto', riga: coperta };
  const inCorso = righe.find((r) => !testo(r.media) && norm(r.stato) === 'in_scrittura' && testo(r.esecuzione));
  if (inCorso) return { scoperto: false, motivo: 'in_lavorazione', riga: inCorso };
  const tentativi = righe.filter(eTentativoNostro).length;
  if (tentativi >= Math.max(intero(cfg.MAX_TENTATIVI_GIORNO, 2), 1)) return { scoperto: false, motivo: 'troppi_tentativi', tentativi };
  const pianificata = righe.find((r) => !testo(r.media) && STATI_PIANIFICATI.includes(norm(r.stato)) && !testo(r.esecuzione)) || null;
  return { scoperto: true, pianificata, tentativi };
}
