const tab = tabella('Rileggi la riga in errore');
const exec = String($execution.id);
const riga = tab.righe.filter((r) => testo(r.id) === testo(e.id) && testo(r.esecuzione) === exec).sort(perRiga)[0];
if (tab.errore || !riga) return [{ json: { sblocca: false } }];
return [{ json: { sblocca: true, row_number: riga.row_number, scrittura: corpoAggiorna(tab, 'Calendario', riga.row_number, { esecuzione: '' }) } }];
